 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Partition at the full-length color-3 lines. Each rectangle is a
    # Sierpinski-like pattern made by recursively dividing it into thirds.
    rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    rbounds = [-1] + rows + [h]
    cbounds = [-1] + cols + [w]

    def is_removed(x, y):
        # A cell is a hole when its local position is in the middle third
        # on both axes at any scale. The examples' regions are near-square.
        while x or y:
            if x % 3 == 1 and y % 3 == 1:
                return True
            x //= 3
            y //= 3
        return False

    for ri in range(len(rbounds) - 1):
        r0, r1 = rbounds[ri] + 1, rbounds[ri + 1]
        for ci in range(len(cbounds) - 1):
            c0, c1 = cbounds[ci] + 1, cbounds[ci + 1]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0 if is_removed(c - c0, r - r0) else 4
    return out
